# ============================================================ #
def get_db():
    """الحصول على اتصال بقاعدة البيانات (PostgreSQL عبر psycopg2)"""
    conn = psycopg2.connect(DATABASE_URL, cursor_factory=psycopg2.extras.RealDictCursor)
    return conn

def _pg_sql(sql):
    """تحويل علامات الاستفهام '?' الخاصة بصيغة SQLite القديمة إلى '%s' التي
    تعتمدها PostgreSQL/psycopg2، حتى لا نضطر لتعديل آلاف الاستدعاءات يدوياً."""
    return sql.replace('?', '%s')

def query_one(sql, params=None):
    """تنفيذ استعلام وإرجاع صف واحد (كقاموس dict)"""
    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute(_pg_sql(sql), params if params else None)
        result = cur.fetchone()
        cur.close()
        return result
    finally:
        conn.close()
def query_all(sql, params=None):
    """تنفيذ استعلام وإرجاع جميع الصفوف (كقائمة قواميس)"""
    conn = get_db()
    try:
        cur = conn.cursor()
        cur.execute(_pg_sql(sql), params if params else None)
        result = cur.fetchall()
        cur.close()
        return result
    finally:
        conn.close()
def execute_query(sql, params=None):
    """تنفيذ استعلام تعديل (INSERT, UPDATE, DELETE).
    عند الإدراج (INSERT) تُعاد قيمة id الصف المُدرج تلقائياً (مثل lastrowid في
    SQLite سابقاً)، وذلك بإضافة RETURNING id عند الحاجة."""
    conn = get_db()
    try:
        cur = conn.cursor()
        pg_sql = _pg_sql(sql)
        is_insert = pg_sql.strip().upper().startswith('INSERT')
        if is_insert and 'RETURNING' not in pg_sql.upper():
            pg_sql = pg_sql.rstrip() + ' RETURNING id'
        cur.execute(pg_sql, params if params else None)
        last_id = None
        if is_insert:
            row = cur.fetchone()
            if row:
                last_id = row['id'] if isinstance(row, dict) else row[0]
        conn.commit()
        cur.close()
        return last_id
    finally:
        conn.close()
def execute_many(sql, params_list):
    """تنفيذ استعلام متعدد (INSERT, UPDATE)"""
    if not params_list:
        return
    conn = get_db()
    try:
        cur = conn.cursor()
        cur.executemany(_pg_sql(sql), params_list)
        conn.commit()
        cur.close()
    finally:
        conn.close()
def table_exists(table_name):
    """التحقق من وجود جدول في قاعدة البيانات"""
    result = query_one(
        "SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name=%s",
        (table_name,)
    )
    return result is not None
def column_exists(table_name, column_name):
    """التحقق من وجود عمود في جدول"""
    result = query_one(
        "SELECT column_name FROM information_schema.columns WHERE table_name=%s AND column_name=%s",
        (table_name, column_name)
    )
    return result is not None
