def login_required(role=None):
    """مزخرف للتحقق من تسجيل الدخول مع دور محدد"""
    def decorator(f):
        @wraps(f)
        def decorated_function(*args, **kwargs):
            if 'user_id' not in session or not session.get('logged_in'):
                flash('الرجاء تسجيل الدخول أولاً', 'danger')
                return redirect(url_for('home'))
            if role and session.get('role') != role:
                # التحقق من صلاحيات المساعد
                if role == 'admin' and session.get('role') == 'assistant':
                    # المساعد له صلاحيات محدودة
                    return f(*args, **kwargs)
                flash('غير مصرح لك بالوصول إلى هذه الصفحة', 'danger')
                return redirect(url_for('home'))
            return f(*args, **kwargs)
        return decorated_function
    return decorator
def is_admin():
    """التحقق من أن المستخدم مشرف"""
    return session.get('role') == 'admin'
def is_student():
    """التحقق من أن المستخدم طالب"""
    return session.get('role') == 'student'
def is_assistant():
    """التحقق من أن المستخدم مساعد"""
    return session.get('role') == 'assistant'
def get_current_user():
    """الحصول على بيانات المستخدم الحالي"""
    if 'user_id' not in session or not session.get('logged_in'):
        return None
    
    role = session.get('role')
    user_id = session.get('user_id')
    
    if role == 'admin':
        return query_one("SELECT * FROM admins WHERE id = ?", (user_id,))
    elif role == 'student':
        return query_one("SELECT * FROM students WHERE id = ?", (user_id,))
    elif role == 'assistant':
        # جلب بيانات المساعد مع صلاحياته
        student = query_one("SELECT * FROM students WHERE id = ?", (user_id,))
        if student:
            assistant = query_one(
                "SELECT * FROM assistants WHERE student_id = ? AND active = 1",
                (user_id,)
            )
            if assistant:
                return dict(student, **dict(assistant))
        return student
    return None
def has_assistant_permission(permission):
    """التحقق من صلاحية المساعد"""
    if session.get('role') != 'assistant' and session.get('role') != 'admin':
        return False
    
    if session.get('role') == 'admin':
        return True
    
    assistant = query_one(
        "SELECT permissions FROM assistants WHERE student_id = ? AND active = 1",
        (session.get('user_id'),)
    )
    if not assistant:
        return False
    perms = assistant['permissions'].split(',') if assistant['permissions'] else []
    return 'view_all' in perms or permission in perms
def create_session(user_id, role, user_data=None):
    """إنشاء جلسة مستخدم"""
    session.clear()
    session['user_id'] = user_id
    session['role'] = role
    session['logged_in'] = True
    session.permanent = True
    
    if user_data:
        session['user_name'] = user_data.get('name', '')
        session['user_email'] = user_data.get('email', '')
    
    return session
def destroy_session():
    """إنهاء الجلسة"""
    session.clear()
def is_logged_in():
    """التحقق من تسجيل الدخول"""
    return session.get('logged_in', False)
