def format_dt(value, fmt='%Y-%m-%d %H:%M'):
    """تنسيق التاريخ والوقت"""
    if not value:
        return ''
    if isinstance(value, str):
        for pattern in ('%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d %H:%M:%S', '%Y-%m-%dT%H:%M:%S.%f', '%Y-%m-%dT%H:%M:%S'):
            try:
                value = datetime.strptime(value, pattern)
                break
            except ValueError:
                continue
        else:
            return value
    try:
        return value.strftime(fmt)
    except Exception:
        return str(value)
app.jinja_env.filters['fmtdt'] = format_dt
def generate_token(length=32):
    """توليد رمز عشوائي"""
    alphabet = string.ascii_letters + string.digits
    return ''.join(secrets.choice(alphabet) for _ in range(length))
def get_today():
    """الحصول على تاريخ اليوم بصيغة YYYY-MM-DD"""
    return datetime.now().strftime('%Y-%m-%d')
def get_today_datetime():
    """الحصول على تاريخ ووقت اليوم"""
