def allowed_file(filename):
    """التحقق من امتداد الملف المسموح به"""
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS
def save_uploaded_file(file, subfolder='', max_size=50*1024*1024):
    """حفظ ملف مرفوع"""
    if not file or file.filename == '':
        return None
    if not allowed_file(file.filename):
        return None
    
    # التحقق من الحجم
    file.seek(0, os.SEEK_END)
    size = file.tell()
    file.seek(0)
    if size > max_size:
        return None
    
    filename = secure_filename(file.filename)
    orig_ext = file.filename.rsplit('.', 1)[-1].lower() if '.' in file.filename else ''
    name_parts = filename.rsplit('.', 1)
    base_name = name_parts[0] if name_parts[0] else 'file'
    ext = name_parts[1] if len(name_parts) > 1 and name_parts[1] else orig_ext
    if not ext:
        ext = 'bin'
    new_filename = f"{datetime.now().strftime('%Y%m%d%H%M%S')}_{secrets.token_hex(4)}_{base_name}.{ext}"
    folder = os.path.join(UPLOAD_FOLDER, subfolder)
    os.makedirs(folder, exist_ok=True)
    filepath = os.path.join(folder, new_filename)
    file.save(filepath)
    return f"/static/uploads/{subfolder}/{new_filename}" if subfolder else f"/static/uploads/{new_filename}"
def delete_file(filepath):
    """حذف ملف"""
    if not filepath:
        return False
    # إزالة /static/uploads/ من المسار
    relative_path = filepath.replace('/static/uploads/', '')
    full_path = os.path.join(UPLOAD_FOLDER, relative_path)
    try:
        if os.path.exists(full_path):
            os.remove(full_path)
            return True
    except:
        pass
    return False
def get_file_size(filepath):
    """الحصول على حجم الملف بالكيلوبايت"""
    try:
        relative_path = filepath.replace('/static/uploads/', '')
        full_path = os.path.join(UPLOAD_FOLDER, relative_path)
        size = os.path.getsize(full_path)
        return round(size / 1024, 1)
    except:
        return 0
def slugify(text):
    """تحويل النص إلى slug"""
    text = text.lower()
    text = re.sub(r'[^a-zA-Z0-9\u0600-\u06FF\s]', '', text)
    text = re.sub(r'\s+', '-', text)
    return text
def get_arabic_date(date_obj=None):
    """الحصول على التاريخ بالعربية"""
    if not date_obj:
        date_obj = datetime.now()
    
    days_ar = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت']
    months_ar = ['يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو', 'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر']
    
    return f"{days_ar[date_obj.weekday()]}، {date_obj.day} {months_ar[date_obj.month-1]} {date_obj.year}"
def get_time_12h(date_obj=None):
    """الحصول على الوقت بصيغة 12 ساعة"""
    if not date_obj:
        date_obj = datetime.now()
    hour = date_obj.hour
    minute = date_obj.minute
    ampm = 'ص' if hour < 12 else 'م'
    hour = hour % 12 or 12
    return f"{hour}:{minute:02d} {ampm}"
def get_date_range(start_date, end_date):
    """الحصول على قائمة التواريخ بين تاريخين"""
    start = datetime.strptime(start_date, '%Y-%m-%d')
    end = datetime.strptime(end_date, '%Y-%m-%d')
    dates = []
    current = start
    while current <= end:
        dates.append(current.strftime('%Y-%m-%d'))
        current += timedelta(days=1)
    return dates
def random_color():
    """توليد لون عشوائي"""
    colors = ['red', 'blue', 'green', 'purple', 'pink', 'orange', 'teal', 'indigo']
    return random.choice(colors)
