def add_points(student_id, amount, reason, type='earned'):
    """إضافة نقاط لطالب"""
    if amount <= 0:
        return False
    
    # إضافة الحركة
    execute_query(
        "INSERT INTO points_transactions (student_id, amount, reason, type) VALUES (?, ?, ?, ?)",
        (student_id, amount, reason, type)
    )
    
    # تحديث النقاط في جدول الطلاب
    sign = '+' if type == 'earned' else '-'
    execute_query(
        f"UPDATE students SET points = points {sign} ? WHERE id = ?",
        (amount, student_id)
    )
    
    # التحقق من الشارات
    check_and_award_badges(student_id)
    return True
def deduct_points(student_id, amount, reason):
    """خصم نقاط من طالب"""
    if amount <= 0:
        return False
    
    # التحقق من وجود رصيد كافٍ
    student = query_one("SELECT points FROM students WHERE id = ?", (student_id,))
    if not student or student['points'] < amount:
        return False
    
    return add_points(student_id, amount, reason, 'spent')
def run_monthly_xp_disbursement():
    """صرف تلقائي لـ 1000 نقطة XP لكل طالب نشط في بداية كل شهر جديد، دون تدخل المشرف"""
    current_month = datetime.now().strftime('%Y-%m')
    students = query_all(
        "SELECT id FROM students WHERE status = 'active' AND (last_monthly_xp IS NULL OR last_monthly_xp != ?)",
        (current_month,)
    )
    for st in students:
        add_points(st['id'], 1000, f"منحة شهرية تلقائية - {current_month}", 'earned')
        execute_query(
            "UPDATE students SET last_monthly_xp = ? WHERE id = ?",
            (current_month, st['id'])
        )
def get_student_points(student_id):
    """الحصول على نقاط الطالب"""
    result = query_one("SELECT points FROM students WHERE id = ?", (student_id,))
    return result['points'] if result else 0
def get_points_transactions(student_id, limit=50):
    """الحصول على حركات النقاط للطالب"""
    return query_all(
        "SELECT * FROM points_transactions WHERE student_id = ? ORDER BY created_at DESC LIMIT ?",
        (student_id, limit)
    )
def check_and_award_badges(student_id):
    """التحقق من استحقاق الشارات ومنحها"""
    # الحصول على نقاط الطالب
    student = query_one("SELECT points FROM students WHERE id = ?", (student_id,))
    if not student:
        return
    
    points = student['points']
    
    # الحصول على الشارات التي حصل عليها الطالب
    earned = query_all(
        "SELECT badge_id FROM student_badges WHERE student_id = ?",
        (student_id,)
    )
    earned_ids = [e['badge_id'] for e in earned]
    
    # تعريف الشارات حسب النقاط
    badges_thresholds = [
        {'id': 1, 'points': 10, 'name': 'الخطوة الأولى', 'icon': '🌱'},
        {'id': 2, 'points': 50, 'name': 'المثابر', 'icon': '💪'},
        {'id': 3, 'points': 100, 'name': 'النجم الصاعد', 'icon': '⭐'},
        {'id': 4, 'points': 250, 'name': 'الحافظ النشيط', 'icon': '📖'},
        {'id': 5, 'points': 500, 'name': 'الملهم', 'icon': '🌟'},
        {'id': 6, 'points': 1000, 'name': 'أسطورة الحفظ', 'icon': '🏆'},
    ]
    
    for badge in badges_thresholds:
        if points >= badge['points'] and badge['id'] not in earned_ids:
            badge_exists = query_one("SELECT id FROM badges WHERE id = ?", (badge['id'],))
            if not badge_exists:
                continue
            execute_query(
                "INSERT INTO student_badges (student_id, badge_id) VALUES (?, ?)",
                (student_id, badge['id'])
            )
def get_all_badges():
    """الحصول على جميع الشارات"""
    return query_all("SELECT * FROM badges ORDER BY id")
def get_student_badges(student_id):
    """الحصول على شارات الطالب التي حصل عليها"""
    return query_all("""
        SELECT b.*, sb.earned_at
        FROM student_badges sb
        JOIN badges b ON b.id = sb.badge_id
        WHERE sb.student_id = ?
        ORDER BY sb.earned_at DESC
    """, (student_id,))
def get_badges_with_status(student_id):
    """الحصول على جميع الشارات مع حالة الطالب"""
    badges = query_all("SELECT * FROM badges ORDER BY id")
    earned = get_student_badges(student_id)
    earned_ids = [b['id'] for b in earned]
    
    result = []
    for badge in badges:
        result.append({
            'id': badge['id'],
            'code': badge['code'],
            'name': badge['name'],
            'description': badge['description'],
            'icon': badge['icon'],
            'earned': badge['id'] in earned_ids,
            'earned_at': next((b['earned_at'] for b in earned if b['id'] == badge['id']), None)
        })
    return result
