def get_student_stats(student_id):
    """الحصول على إحصائيات الطالب"""
    # عدد التقييمات
    evals = query_one(
        "SELECT COUNT(*) as count FROM daily_evaluations WHERE student_id = ?",
        (student_id,)
    )
    # عدد النقاط
    points = query_one(
        "SELECT points FROM students WHERE id = ?",
        (student_id,)
    )
    # عدد الشارات
    badges = query_one(
        "SELECT COUNT(*) as count FROM student_badges WHERE student_id = ?",
        (student_id,)
    )
    # عدد الواجبات المسلمة
    homework = query_one(
        "SELECT COUNT(*) as count FROM homework_submissions WHERE student_id = ?",
        (student_id,)
    )
    # متوسط الدرجات
    avg = query_one("""
        SELECT AVG(score_save) as avg_save, AVG(score_rev) as avg_rev, AVG(homework_score) as avg_hw
        FROM daily_evaluations WHERE student_id = ?
    """, (student_id,))
    
    return {
        'evaluations': evals['count'] if evals else 0,
        'points': points['points'] if points else 0,
        'badges': badges['count'] if badges else 0,
        'homework': homework['count'] if homework else 0,
        'avg_save': round(avg['avg_save'], 1) if avg and avg['avg_save'] else 0,
        'avg_rev': round(avg['avg_rev'], 1) if avg and avg['avg_rev'] else 0,
        'avg_hw': round(avg['avg_hw'], 1) if avg and avg['avg_hw'] else 0,
    }
def get_student_rank(student_id):
    """الحصول على ترتيب الطالب بين أقرانه"""
    result = query_one("""
        SELECT COUNT(*) + 1 as rank
        FROM students
        WHERE points > (SELECT points FROM students WHERE id = ?)
        AND status = 'active'
    """, (student_id,))
    return result['rank'] if result else 0
