def register_student_for_competition(student_id, comp_id):
    """تسجيل طالب في مسابقة"""
    # التحقق من وجود التسجيل
    existing = get_student_competition_grade(student_id, comp_id)
    if existing:
        return False
    
    # الحصول على تكلفة التسجيل
    comp = get_competition_by_id(comp_id)
    if not comp:
        return False
    
    cost = comp['registration_cost'] or 0
    
    # خصم النقاط إذا كانت مطلوبة
    if cost > 0:
        if not deduct_points(student_id, cost, f"تسجيل في مسابقة: {comp['name']}"):
            return False
    
    # إضافة التسجيل
    execute_query(
        "INSERT INTO competition_grades (student_id, competition_id, grade) VALUES (?, ?, 0)",
        (student_id, comp_id)
    )
    return True
