    return query_all("""
        SELECT c.*, cg.grade as my_grade,
               (SELECT COUNT(*) + 1 FROM competition_grades WHERE competition_id = c.id AND grade > cg.grade) as my_rank
        FROM competitions c
        LEFT JOIN competition_grades cg ON cg.competition_id = c.id AND cg.student_id = ?
        ORDER BY c.date DESC
    """, (student_id,))
