# ====== SECTION 14: SESSION HELPERS ========================== #
# ============================================================ #
def create_admin_session(admin_id, name, email):
    """إنشاء جلسة مشرف"""
    session.clear()
    session['user_id'] = admin_id
    session['role'] = 'admin'
    session['logged_in'] = True
    session['user_name'] = name
    session['user_email'] = email
    session.permanent = True
def create_student_session(student_id, name, email):
    """إنشاء جلسة طالب"""
    session.clear()
    session['user_id'] = student_id
    session['role'] = 'student'
    session['logged_in'] = True
    session['user_name'] = name
    session['user_email'] = email
    session.permanent = True
def create_assistant_session(student_id, name, email):
    """إنشاء جلسة مساعد"""
    session.clear()
    session['user_id'] = student_id
    session['role'] = 'assistant'
    session['logged_in'] = True
    session['user_name'] = name
    session['user_email'] = email
    session.permanent = True
# ============================================================ #
# ====== SECTION 15: INIT DATABASE ============================ #
# ============================================================ #
def init_db():
    """تهيئة قاعدة البيانات مع جميع الجداول"""
    conn = get_db()
    cur = conn.cursor()
    
    # جدول المديرين
    cur.execute("""
    CREATE TABLE IF NOT EXISTS admins (
        id SERIAL PRIMARY KEY,
        username VARCHAR(100) UNIQUE NOT NULL,
        password VARCHAR(255) NOT NULL,
        name VARCHAR(255) NOT NULL,
        email VARCHAR(255),
        phone VARCHAR(50),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول الطلاب
    cur.execute("""
    CREATE TABLE IF NOT EXISTS students (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        email VARCHAR(255) UNIQUE NOT NULL,
        password VARCHAR(255) NOT NULL,
        phone VARCHAR(50),
        parent_phone VARCHAR(50),
        address TEXT,
        rank INTEGER DEFAULT 0,
        join_date DATE DEFAULT CURRENT_DATE,
        status VARCHAR(50) DEFAULT 'active',
        payment_status VARCHAR(50) DEFAULT 'pending',
        notes TEXT,
        points INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول طلبات التسجيل
    cur.execute("""
    CREATE TABLE IF NOT EXISTS registration_requests (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        email VARCHAR(255) UNIQUE NOT NULL,
        password VARCHAR(255) NOT NULL,
        phone VARCHAR(50),
        parent_phone VARCHAR(50),
        address TEXT,
        status VARCHAR(50) DEFAULT 'pending',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول الشارات
    cur.execute("""
    CREATE TABLE IF NOT EXISTS badges (
        id SERIAL PRIMARY KEY,
        code VARCHAR(50) UNIQUE NOT NULL,
        name VARCHAR(255) NOT NULL,
        description TEXT,
        icon VARCHAR(10) DEFAULT '🏅'
    )
    """)
    
    # جدول شارات الطلاب
    cur.execute("""
    CREATE TABLE IF NOT EXISTS student_badges (
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        badge_id INTEGER NOT NULL REFERENCES badges(id) ON DELETE CASCADE,
        earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (student_id, badge_id)
    )
    """)
    
    # جدول حركات النقاط
    cur.execute("""
    CREATE TABLE IF NOT EXISTS points_transactions (
        id SERIAL PRIMARY KEY,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        amount INTEGER NOT NULL,
        reason VARCHAR(255),
        type VARCHAR(20) NOT NULL,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول التقييمات اليومية
    cur.execute("""
    CREATE TABLE IF NOT EXISTS daily_evaluations (
        id SERIAL PRIMARY KEY,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        date DATE NOT NULL,
        curr_save VARCHAR(255),
        score_save NUMERIC DEFAULT 0,
        curr_rev VARCHAR(255),
        score_rev NUMERIC DEFAULT 0,
        homework_score NUMERIC DEFAULT 0,
        notes TEXT,
        sent INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(student_id, date)
    )
    """)
    
    # جدول الواجبات
    cur.execute("""
    CREATE TABLE IF NOT EXISTS homework (
        id SERIAL PRIMARY KEY,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        date DATE NOT NULL,
        details TEXT,
        notes TEXT,
        sent INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        UNIQUE(student_id, date)
    )
    """)
    
    # جدول تسليم الواجبات
    cur.execute("""
    CREATE TABLE IF NOT EXISTS homework_submissions (
        id SERIAL PRIMARY KEY,
        homework_id INTEGER NOT NULL REFERENCES homework(id) ON DELETE CASCADE,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        content TEXT,
        file_url TEXT,
        grade NUMERIC,
        feedback TEXT,
        submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول المسابقات
    cur.execute("""
    CREATE TABLE IF NOT EXISTS competitions (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        description TEXT,
        max_grade NUMERIC DEFAULT 10,
        date DATE DEFAULT CURRENT_DATE,
        active INTEGER DEFAULT 1,
        is_open INTEGER DEFAULT 1,
        registration_cost INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول درجات المسابقات
    cur.execute("""
    CREATE TABLE IF NOT EXISTS competition_grades (
        student_id INTEGER REFERENCES students(id) ON DELETE CASCADE,
        competition_id INTEGER REFERENCES competitions(id) ON DELETE CASCADE,
        grade NUMERIC DEFAULT 0,
        notes TEXT,
        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (student_id, competition_id)
    )
    """)
    
    # جدول التحديات الفردية
    cur.execute("""
    CREATE TABLE IF NOT EXISTS duels (
        id SERIAL PRIMARY KEY,
        challenger_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        opponent_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        duel_type VARCHAR(100) DEFAULT 'حفظ',
        custom_type VARCHAR(255),
        wager_points INTEGER DEFAULT 0,
        status VARCHAR(50) DEFAULT 'pending',
        winner_id INTEGER REFERENCES students(id) ON DELETE SET NULL,
        admin_note TEXT,
        scheduled_at TIMESTAMP,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول المساعدين
    cur.execute("""
    CREATE TABLE IF NOT EXISTS assistants (
        id SERIAL PRIMARY KEY,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        permissions TEXT DEFAULT '',
        xp_points INTEGER DEFAULT 0,
        xp_due_date DATE,
        last_xp_granted TIMESTAMP,
        active INTEGER DEFAULT 1,
        granted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول حركات XP للمساعدين
    cur.execute("""
    CREATE TABLE IF NOT EXISTS xp_transactions (
        id SERIAL PRIMARY KEY,
        assistant_id INTEGER NOT NULL REFERENCES assistants(id) ON DELETE CASCADE,
        amount INTEGER NOT NULL,
        reason VARCHAR(255),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول مهام المساعدين
    cur.execute("""
    CREATE TABLE IF NOT EXISTS assistant_tasks (
        id SERIAL PRIMARY KEY,
        assistant_id INTEGER NOT NULL REFERENCES assistants(id) ON DELETE CASCADE,
        title VARCHAR(255) NOT NULL,
        description TEXT,
        status VARCHAR(50) DEFAULT 'pending',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        completed_at TIMESTAMP
    )
    """)
    
    # جدول الرسائل
    cur.execute("""
    CREATE TABLE IF NOT EXISTS messages (
        id SERIAL PRIMARY KEY,
        sender_id INTEGER NOT NULL,
        sender_type VARCHAR(50) NOT NULL,
        receiver_id INTEGER NOT NULL,
        message TEXT NOT NULL,
        file_url TEXT,
        is_group INTEGER DEFAULT 0,
        group_id INTEGER,
        is_read INTEGER DEFAULT 0,
        is_delivered INTEGER DEFAULT 1,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول مجموعات الرسائل
    cur.execute("""
    CREATE TABLE IF NOT EXISTS message_groups (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        color VARCHAR(50) DEFAULT 'purple',
        created_by INTEGER,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول أعضاء المجموعات
    cur.execute("""
    CREATE TABLE IF NOT EXISTS group_members (
        id SERIAL PRIMARY KEY,
        group_id INTEGER NOT NULL,
        student_id INTEGER NOT NULL,
        joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (group_id) REFERENCES message_groups(id) ON DELETE CASCADE,
        FOREIGN KEY (student_id) REFERENCES students(id) ON DELETE CASCADE
    )
    """)
    
    # جدول الكتب
    cur.execute("""
    CREATE TABLE IF NOT EXISTS books (
        id SERIAL PRIMARY KEY,
        title VARCHAR(255) NOT NULL,
        author VARCHAR(255),
        description TEXT,
        price_points INTEGER DEFAULT 0,
        quantity INTEGER DEFAULT 1,
        cover_url TEXT,
        pdf_url TEXT,
        seller_student_id INTEGER REFERENCES students(id) ON DELETE SET NULL,
        active INTEGER DEFAULT 1,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول عروض بيع الكتب
    cur.execute("""
    CREATE TABLE IF NOT EXISTS book_offers (
        id SERIAL PRIMARY KEY,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        title VARCHAR(255) NOT NULL,
        author VARCHAR(255),
        description TEXT,
        price_points INTEGER DEFAULT 0,
        status VARCHAR(50) DEFAULT 'pending',
        admin_note TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول مشتريات الكتب
    cur.execute("""
    CREATE TABLE IF NOT EXISTS book_purchases (
        id SERIAL PRIMARY KEY,
        student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
        book_id INTEGER NOT NULL REFERENCES books(id) ON DELETE CASCADE,
        price_paid INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول الشهور
    cur.execute("""
    CREATE TABLE IF NOT EXISTS months (
        id SERIAL PRIMARY KEY,
        name VARCHAR(255) NOT NULL,
        hijri_year VARCHAR(50),
        gregorian_year VARCHAR(50),
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # جدول الحصص
    cur.execute("""
    CREATE TABLE IF NOT EXISTS sessions (
        id SERIAL PRIMARY KEY,
        month_id INTEGER NOT NULL REFERENCES months(id) ON DELETE CASCADE,
        date DATE NOT NULL,
        title VARCHAR(255) NOT NULL,
        session_type VARCHAR(50) DEFAULT 'حفظ',
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # إضافة عمود session_id إلى daily_evaluations إذا لم يكن موجوداً
    try:
        cur.execute("ALTER TABLE daily_evaluations ADD COLUMN IF NOT EXISTS session_id INTEGER REFERENCES sessions(id) ON DELETE SET NULL")
    except Exception:
        conn.rollback()
    
    # إضافة عمود file_name إلى homework
    try:
        cur.execute("ALTER TABLE homework ADD COLUMN IF NOT EXISTS file_name VARCHAR(255)")
    except Exception:
        conn.rollback()
    
    # إضافة عمود file_url و submitted إلى homework
    try:
        cur.execute("ALTER TABLE homework ADD COLUMN IF NOT EXISTS file_url TEXT")
    except Exception:
        conn.rollback()
    try:
        cur.execute("ALTER TABLE homework ADD COLUMN IF NOT EXISTS submitted INTEGER DEFAULT 0")
    except Exception:
        conn.rollback()
    
    # إضافة عمود registration_cost إلى competitions
    try:
        cur.execute("ALTER TABLE competitions ADD COLUMN IF NOT EXISTS registration_cost INTEGER DEFAULT 0")
    except Exception:
        conn.rollback()
    
    # إضافة عمود is_open إلى competitions
    try:
        cur.execute("ALTER TABLE competitions ADD COLUMN IF NOT EXISTS is_open INTEGER DEFAULT 1")
    except Exception:
        conn.rollback()
    
    # ============================================================ #
    # ====== SEED DATA ============================================ #
    # ============================================================ #
    
    # إضافة الشارات الأساسية
    cur.execute("""
        INSERT INTO badges (code, name, description, icon)
        VALUES
            ('first_step', 'الخطوة الأولى', 'أكمل أول تقييم يومي', '🌱'),
            ('week_streak', 'أسبوع كامل', '7 أيام متتالية من الحضور', '🔥'),
            ('top_ten', 'من العشرة الأوائل', 'دخل قائمة أفضل 10 طلاب', '⭐'),
            ('competition_winner', 'بطل مسابقة', 'فاز في إحدى المسابقات', '🏆'),
            ('duel_master', 'سيد التحديات', 'فاز في 3 تحديات فردية', '⚔️'),
            ('xp_legend', 'أسطورة الحفظ', 'وصل إلى 1000 نقطة XP', '🏅')
        ON CONFLICT (code) DO NOTHING
    """)
    
    # إضافة المشرف الافتراضي
    cur.execute("SELECT * FROM admins WHERE username = %s", ('الشيخ',))
    if not cur.fetchone():
        hashed_pw = generate_password_hash('بومسلة العيد')
        cur.execute(
            "INSERT INTO admins (username, password, name, email) VALUES (%s, %s, %s, %s)",
            ('الشيخ', hashed_pw, 'أبو عمر بومسلة العيد', 'admin@quran.com')
        )
    
    # إضافة طالب افتراضي
    cur.execute("SELECT * FROM students WHERE email = %s", ('yacinezaoui2010@gmail.com',))
    if not cur.fetchone():
        hashed_pw = generate_password_hash('*yacinezaoui2010#')
        cur.execute("""
            INSERT INTO students (name, email, password, phone, rank, status, payment_status)
            VALUES (%s, %s, %s, %s, %s, %s, %s)
        """, ('ياسين زاوي', 'yacinezaoui2010@gmail.com', hashed_pw, '0665450555', 1, 'active', 'paid'))
    
    # جدول سجل إجراءات المساعدين
    cur.execute("""
    CREATE TABLE IF NOT EXISTS assistant_actions (
        id SERIAL PRIMARY KEY,
        assistant_id INTEGER NOT NULL,
        action_type VARCHAR(100),
        description TEXT,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (assistant_id) REFERENCES students(id) ON DELETE CASCADE
    )
    """)
    
    # جدول إعادة تعيين كلمة المرور
    cur.execute("""
    CREATE TABLE IF NOT EXISTS password_resets (
        id SERIAL PRIMARY KEY,
        user_type VARCHAR(20) NOT NULL,
        user_id INTEGER NOT NULL,
        token VARCHAR(64) UNIQUE NOT NULL,
        expires_at TIMESTAMP NOT NULL,
        used INTEGER DEFAULT 0,
        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )
    """)
    
    # ==========================================
    # ترحيل قاعدة البيانات: إضافة أي أعمدة ناقصة لقواعد بيانات قديمة
    # ==========================================
    migrations = {
        'messages': [('group_id', 'INTEGER'), ('is_group', 'INTEGER DEFAULT 0'), ('file_url', 'TEXT'), ('receiver_type', 'VARCHAR(20)')],
        'sessions': [('student_id', 'INTEGER REFERENCES students(id) ON DELETE CASCADE')],
        'students': [('last_monthly_xp', 'VARCHAR(7)')],
        'competitions': [('rewarded', 'INTEGER DEFAULT 0')],
        'assistants': [('xp_due_date', 'DATE')],
    }
    for table_name, columns in migrations.items():
        cur.execute(
            "SELECT column_name FROM information_schema.columns WHERE table_schema='public' AND table_name=%s",
            (table_name,)
        )
        existing_cols = {row['column_name'] for row in cur.fetchall()}
        for col_name, col_def in columns:
            if col_name not in existing_cols:
                try:
                    cur.execute(f"ALTER TABLE {table_name} ADD COLUMN IF NOT EXISTS {col_name} {col_def}")
                except Exception:
                    conn.rollback()
    
    # تعبئة receiver_type للرسائل القديمة (قبل إضافة العمود) بأفضل تخمين ممكن:
    # رسائل المجموعات مستقبلها دائماً طالب، والرسائل الفردية نوع مستقبلها
    # عكس نوع المرسل (لأن التراسل الفردي في هذا النظام يكون بين مشرف وطالب
    # أو بين طالبين، وفي كلتا الحالتين النوع الافتراضي الأقرب للصواب هو
    # الطالب، إلا إذا كان معرف المستقبل موجوداً فعلياً في جدول admins).
    try:
        cur.execute("SELECT id, receiver_id FROM messages WHERE receiver_type IS NULL AND (is_group = 1 OR is_group = '1')")
        rows = cur.fetchall()
        for row in rows:
            cur.execute("UPDATE messages SET receiver_type = 'student' WHERE id = %s", (row['id'],))
        cur.execute("SELECT id, receiver_id FROM messages WHERE receiver_type IS NULL AND (is_group = 0 OR is_group IS NULL)")
        rows = cur.fetchall()
        for row in rows:
            msg_id, receiver_id = row['id'], row['receiver_id']
            cur.execute("SELECT 1 FROM admins WHERE id = %s", (receiver_id,))
            is_admin_receiver = cur.fetchone()
            cur.execute("SELECT 1 FROM students WHERE id = %s", (receiver_id,))
            is_student_receiver = cur.fetchone()
            if is_admin_receiver and not is_student_receiver:
                cur.execute("UPDATE messages SET receiver_type = 'admin' WHERE id = %s", (msg_id,))
            else:
                cur.execute("UPDATE messages SET receiver_type = 'student' WHERE id = %s", (msg_id,))
    except Exception:
        conn.rollback()
    
    conn.commit()
    cur.close()
    conn.close()
    print("✅ قاعدة البيانات جاهزة!")
