STUDENT_REPORT_HTML = '''
<!DOCTYPE html>
<html dir="rtl" lang="ar">
<head>
    <link rel="icon" type="image/png" href="{{ url_for('static', filename='logo.png') }}">
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>تقريري - حلقتي زتاي</title>
    <link href="https://fonts.googleapis.com/css2?family=Tajawal:wght@300;400;500;700;800;900&display=swap" rel="stylesheet">
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
    <style>
        /* ==========================================
                   SECTION 1: المتغيرات الأساسية
                   ========================================== */
        * { margin: 0; padding: 0; box-sizing: border-box; }
        
        :root {
            --primary: #134e5e;
            --primary-light: #1a7a8e;
            --primary-dark: #0a2a32;
            --gold: #c9a227;
            --gold-light: #e8c84a;
            --gold-glow: rgba(201,162,39,0.15);
            --glass: rgba(255,255,255,0.06);
            --glass-border: rgba(255,255,255,0.10);
            --text-primary: #ffffff;
            --text-secondary: rgba(255,255,255,0.7);
            --text-muted: rgba(255,255,255,0.35);
            --shadow: 0 8px 32px rgba(0,0,0,0.3);
            --transition: 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
            --success: #4ade80;
            --danger: #f87171;
            --warning: #fbbf24;
            --info: #60a5fa;
        }

        /* ==========================================
                   SECTION 2: الأساسيات
                   ========================================== */
        body {
            font-family: 'Tajawal', sans-serif;
            background: var(--primary-dark);
            min-height: 100vh;
            color: var(--text-primary);
            overflow-x: hidden;
        }

        .bg-layer {
            position: fixed;
            inset: 0;
            z-index: 0;
            pointer-events: none;
            background:
                radial-gradient(ellipse 60% 40% at 30% 20%, rgba(26,122,142,0.08), transparent),
                radial-gradient(ellipse 50% 30% at 70% 80%, rgba(201,162,39,0.04), transparent);
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 16px 20px 30px;
            position: relative;
            z-index: 1;
        }

        /* ==========================================
                   SECTION 3: الأزرار
                   ========================================== */
        .btn {
            padding: 7px 16px;
            border: none;
            border-radius: 8px;
            font-weight: 600;
            font-size: 13px;
            cursor: pointer;
            transition: all var(--transition);
            text-decoration: none;
            display: inline-flex;
            align-items: center;
            gap: 6px;
            font-family: inherit;
        }
        .btn:hover {
            transform: translateY(-2px);
            box-shadow: 0 4px 16px rgba(0,0,0,0.3);
        }
        .btn-primary { background: var(--primary-light); color: #fff; }
        .btn-gold { background: linear-gradient(135deg, var(--gold), var(--gold-light)); color: #1a1a1a; }
        .btn-outline { background: transparent; border: 1.5px solid var(--glass-border); color: var(--text-secondary); }
        .btn-outline:hover { border-color: var(--gold); color: #fff; }
        .btn-success { background: var(--success); color: #1a1a1a; }
        .btn-danger { background: var(--danger); color: #fff; }
        .btn-warning { background: var(--warning); color: #1a1a1a; }
        .btn-info { background: var(--info); color: #1a1a1a; }
        .btn-sm { padding: 4px 12px; font-size: 12px; }
        .btn-xs { padding: 2px 10px; font-size: 11px; }

        /* ==========================================
                   SECTION 4: الهيدر والتنقل
                   ========================================== */
        .header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 12px;
            padding: 14px 22px;
            background: var(--glass);
            border: 1px solid var(--glass-border);
            border-radius: 14px;
            margin-bottom: 16px;
            backdrop-filter: blur(10px);
        }

        .header h1 {
            font-size: 22px;
            font-weight: 800;
            display: flex;
            align-items: center;
            gap: 8px;
        }
        .header h1 .highlight {
            background: linear-gradient(135deg, var(--gold-light), var(--primary-light));
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            background-clip: text;
        }

        .header .actions {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
        }

        .nav-bar {
            display: flex;
            flex-wrap: wrap;
            gap: 4px;
            margin-bottom: 16px;
            padding: 10px 16px;
            background: var(--glass);
            border: 1px solid var(--glass-border);
            border-radius: 14px;
            backdrop-filter: blur(10px);
        }

        .nav-bar a {
            color: var(--text-muted);
            text-decoration: none;
            padding: 6px 14px;
            border-radius: 8px;
            font-size: 13px;
            font-weight: 500;
            transition: all 0.3s ease;
        }
        .nav-bar a:hover {
            background: rgba(255,255,255,0.04);
            color: var(--text-primary);
        }
        .nav-bar a.active {
            background: var(--gold);
            color: #1a1a1a;
        }

        /* ==========================================
                   SECTION 5: الإحصائيات
                   ========================================== */
        .stats-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
            gap: 14px;
            margin-bottom: 20px;
        }

        .stat-card {
            background: var(--glass);
            border: 1px solid var(--glass-border);
            border-radius: 12px;
            padding: 16px 18px;
            backdrop-filter: blur(10px);
            text-align: center;
        }
        .stat-card .number {
            font-size: 26px;
            font-weight: 900;
            color: var(--gold-light);
        }
        .stat-card .label {
            font-size: 13px;
            color: var(--text-muted);
        }
        .stat-card .sub {
            font-size: 12px;
            color: var(--text-secondary);
            margin-top: 2px;
        }

        /* ==========================================
                   SECTION 6: الشهور
                   ========================================== */
        .months-tabs {
            display: flex;
            gap: 6px;
            flex-wrap: wrap;
            margin-bottom: 16px;
            padding: 8px 12px;
            background: var(--glass);
            border: 1px solid var(--glass-border);
            border-radius: 14px;
            backdrop-filter: blur(10px);
        }

        .months-tabs .month-tab {
            padding: 6px 16px;
            border-radius: 20px;
            border: 1px solid var(--glass-border);
            background: transparent;
            color: var(--text-muted);
            font-size: 13px;
            cursor: pointer;
            transition: all 0.3s ease;
            font-family: inherit;
        }

        .months-tabs .month-tab:hover {
            border-color: var(--text-secondary);
            color: #fff;
        }

        .months-tabs .month-tab.active {
            background: var(--gold);
            color: #1a1a1a;
            border-color: var(--gold);
        }

        .months-tabs .month-tab .badge {
            font-size: 10px;
            background: rgba(255,255,255,0.1);
            padding: 1px 8px;
            border-radius: 12px;
            margin-right: 4px;
        }

        .months-tabs .month-tab.active .badge {
            background: rgba(0,0,0,0.1);
        }

        /* ==========================================
                   SECTION 7: مخططات الشهر
                   ========================================== */
        .month-content {
            display: none;
        }

        .month-content.active {
            display: block;
            animation: fadeIn 0.3s ease;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .charts-grid {
            display: grid;
            grid-template-columns: 2fr 1fr;
            gap: 16px;
            margin-bottom: 20px;
        }

        @media (max-width: 768px) {
            .charts-grid { grid-template-columns: 1fr; }
        }

        .chart-panel {
            background: var(--glass);
            border: 1px solid var(--glass-border);
            border-radius: 14px;
            padding: 18px 20px;
            backdrop-filter: blur(10px);
        }

        .chart-panel .panel-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
            flex-wrap: wrap;
            gap: 8px;
        }

        .chart-panel .panel-header h3 {
            font-size: 16px;
            font-weight: 700;
        }

        .chart-container {
            height: 200px;
            position: relative;
        }

        .chart-container canvas {
            width: 100% !important;
            height: 100% !important;
        }

        /* ==========================================
                   SECTION 8: جدول الحصص
                   ========================================== */
        .table-panel {
            background: var(--glass);
            border: 1px solid var(--glass-border);
            border-radius: 14px;
            padding: 18px 20px;
            backdrop-filter: blur(10px);
            margin-bottom: 20px;
        }

        .table-panel .panel-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
            flex-wrap: wrap;
            gap: 8px;
        }

        .table-panel .panel-header h3 {
            font-size: 17px;
            font-weight: 700;
        }

        .table-responsive {
            overflow-x: auto;
        }

        table {
            width: 100%;
            border-collapse: collapse;
            font-size: 13px;
        }

        table th {
            background: rgba(255,255,255,0.03);
            padding: 8px 10px;
            text-align: center;
            border-bottom: 2px solid var(--glass-border);
            font-weight: 700;
            color: var(--text-muted);
        }

        table td {
            padding: 8px 10px;
            border-bottom: 1px solid var(--glass-border);
            vertical-align: middle;
            text-align: center;
        }

        table tr:hover {
            background: rgba(255,255,255,0.02);
        }

        table tr.high-score {
            background: rgba(74,222,128,0.04);
        }

        table tr.low-score {
            background: rgba(248,113,113,0.04);
        }

        .session-badge {
            display: inline-block;
            padding: 2px 8px;
            border-radius: 10px;
            font-size: 11px;
            font-weight: 600;
        }

        .session-badge.completed {
            background: rgba(74,222,128,0.15);
            color: var(--success);
        }

        .session-badge.pending {
            background: rgba(251,191,36,0.15);
            color: var(--warning);
        }

        /* ==========================================
                   SECTION 9: التوصيات
                   ========================================== */
        .recommendations {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 14px;
            margin-top: 20px;
        }

        @media (max-width: 600px) {
            .recommendations { grid-template-columns: 1fr; }
        }

        .rec-card {
            background: var(--glass);
            border: 1px solid var(--glass-border);
            border-radius: 12px;
            padding: 14px 18px;
            backdrop-filter: blur(10px);
        }

        .rec-card .title {
            font-size: 14px;
            font-weight: 700;
            color: var(--gold-light);
        }

        .rec-card .desc {
            font-size: 13px;
            color: var(--text-secondary);
            margin-top: 4px;
        }

        .rec-card .action {
            font-size: 12px;
            margin-top: 6px;
            padding: 4px 10px;
            border-radius: 6px;
            display: inline-block;
        }

        .rec-card .action.good {
            color: var(--success);
            background: rgba(74,222,128,0.08);
            border: 1px solid rgba(74,222,128,0.1);
        }

        .rec-card .action.warning {
            color: var(--warning);
            background: rgba(251,191,36,0.08);
            border: 1px solid rgba(251,191,36,0.1);
        }

        .rec-card .action.info {
            color: var(--info);
            background: rgba(96,165,250,0.08);
            border: 1px solid rgba(96,165,250,0.1);
        }

        .rec-card .action.danger {
            color: var(--danger);
            background: rgba(248,113,113,0.08);
            border: 1px solid rgba(248,113,113,0.1);
        }

        /* ==========================================
                   SECTION 10: إحصائيات الشهر السريعة
                   ========================================== */
        .month-stats {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            gap: 8px;
            margin-bottom: 16px;
        }

        .month-stat {
            background: rgba(255,255,255,0.03);
            border: 1px solid var(--glass-border);
            border-radius: 8px;
            padding: 8px 12px;
            text-align: center;
        }

        .month-stat .num {
            font-size: 18px;
            font-weight: 700;
            color: var(--gold-light);
        }

        .month-stat .label {
            font-size: 11px;
            color: var(--text-muted);
        }

        /* ==========================================
                   SECTION 11: رسائل التنبيه
                   ========================================== */
        .toast {
            position: fixed;
            bottom: 30px;
            left: 30px;
            padding: 14px 24px;
            border-radius: 12px;
            background: var(--primary-dark);
            border: 1px solid var(--glass-border);
            backdrop-filter: blur(20px);
            box-shadow: var(--shadow);
            z-index: 2000;
            display: none;
            animation: slideUp 0.3s ease;
            max-width: 400px;
        }

        .toast.show {
            display: block;
        }

        .toast .title {
            font-weight: 700;
            font-size: 15px;
        }

        .toast .message {
            font-size: 13px;
            color: var(--text-secondary);
        }

        .toast.success {
            border-color: var(--success);
        }
        .toast.success .title {
            color: var(--success);
        }

        .toast.error {
            border-color: var(--danger);
        }
        .toast.error .title {
            color: var(--danger);
        }

        .toast.info {
            border-color: var(--gold);
        }
        .toast.info .title {
            color: var(--gold-light);
        }

        @keyframes slideUp {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }

        /* ==========================================
                   SECTION 12: التجاوب مع الشاشات
                   ========================================== */
        @media (max-width: 768px) {
            .header {
                flex-direction: column;
                align-items: stretch;
                text-align: center;
            }
            .header .actions {
                justify-content: center;
            }
            .container {
                padding: 12px;
            }
            .nav-bar {
                justify-content: center;
            }
            .stats-grid {
                grid-template-columns: repeat(2, 1fr);
            }
            .charts-grid {
                grid-template-columns: 1fr;
            }
            .recommendations {
                grid-template-columns: 1fr;
            }
            .months-tabs {
                justify-content: center;
            }
            .month-stats {
                grid-template-columns: repeat(2, 1fr);
            }
        }

        @media (max-width: 480px) {
            .stats-grid {
                grid-template-columns: 1fr;
            }
            .table-panel {
                padding: 10px;
            }
            .month-stats {
                grid-template-columns: 1fr;
            }
        }
    </style>
</head>

<body>
    <img src="{{ url_for('static', filename='logo.png') }}" alt="شعار الحلقة" style="position:fixed;top:10px;left:10px;width:44px;height:44px;border-radius:10px;z-index:9999;box-shadow:0 2px 8px rgba(0,0,0,0.25);">
    <div class="bg-layer"></div>
    <div class="container">

        <!-- ===== HEADER ===== -->
        <div class="header">
            <h1>📊 <span class="highlight">تقريري</span></h1>
            <div class="actions">
                <button class="btn btn-outline btn-sm" onclick="exportReport()">📥 تصدير التقرير</button>
                <button class="btn btn-outline btn-sm" onclick="printReport()">🖨️ طباعة</button>
                <a href="{{ url_for('student_dashboard') }}" class="btn btn-outline btn-sm">⬅ الرئيسية</a>
            </div>
        </div>

        <!-- ===== شريط التنقل ===== -->
        <div class="nav-bar">
            <a href="{{ url_for('student_dashboard') }}">📊 الرئيسية</a>
            <a href="{{ url_for('student_homework') }}">📚 واجباتي</a>
            <a href="{{ url_for('student_report') }}" class="active">📊 تقريري</a>
            <a href="{{ url_for('student_competitions') }}">🏆 مسابقاتي</a>
            <a href="{{ url_for('student_messages') }}">💬 رسائلي</a>
            <a href="{{ url_for('student_gamification') }}">🎮 نقاطي وشاراتي</a>
            <a href="{{ url_for('student_points') }}">💰 رصيدي</a>
            <a href="{{ url_for('student_store') }}">🛍️ المتجر</a>
            <a href="{{ url_for('student_duels') }}">⚔️ تحدياتي</a>
            <a href="{{ url_for('leaderboard') }}">🥇 لوحة الصدارة</a>
        </div>

        <!-- ===== الإحصائيات العامة ===== -->
        <div class="stats-grid">
            <div class="stat-card">
                <div class="number">{{ total_months }}</div>
                <div class="label">📅 إجمالي الشهور</div>
            </div>
            <div class="stat-card">
                <div class="number">{{ total_sessions }}</div>
                <div class="label">📚 إجمالي الحصص</div>
            </div>
            <div class="stat-card">
                <div class="number">{{ avg_save|default(0, true) }}</div>
                <div class="label">📖 متوسط الحفظ</div>
                <div class="sub">من 10</div>
            </div>
            <div class="stat-card">
                <div class="number">{{ avg_rev|default(0, true) }}</div>
                <div class="label">📖 متوسط المراجعة</div>
                <div class="sub">من 10</div>
            </div>
            <div class="stat-card">
                <div class="number">{{ avg_homework|default(0, true) }}</div>
                <div class="label">📝 متوسط الواجب</div>
                <div class="sub">من 10</div>
            </div>
            <div class="stat-card">
                <div class="number">{{ total_score|default(0, true) }}</div>
                <div class="label">⭐ مجموع الدرجات</div>
            </div>
        </div>

        <!-- ===== تبويبات الشهور ===== -->
        <div class="months-tabs">
            {% for month in months %}
            <button class="month-tab {% if loop.index == 1 %}active{% endif %}" 
                    data-month="{{ month.id }}" 
                    onclick="switchMonth('{{ month.id }}')">
                📅 {{ month.name }}
                <span class="badge">{{ month.sessions|length if month.sessions else 0 }}</span>
            </button>
            {% else %}
            <span style="color:var(--text-muted);padding:4px 0;">لا توجد شهور مسجلة</span>
            {% endfor %}
        </div>

        <!-- ===== محتوى الشهور ===== -->
        {% for month in months %}
        <div class="month-content {% if loop.index == 1 %}active{% endif %}" id="month-{{ month.id }}">
            
            <!-- إحصائيات الشهر -->
            <div class="month-stats">
                <div class="month-stat">
                    <div class="num">{{ month.sessions|length if month.sessions else 0 }}</div>
                    <div class="label">📚 عدد الحصص</div>
                </div>
                <div class="month-stat">
                    <div class="num">{{ month.avg_save|default(0, true) }}</div>
                    <div class="label">📖 متوسط الحفظ</div>
                </div>
                <div class="month-stat">
                    <div class="num">{{ month.avg_rev|default(0, true) }}</div>
                    <div class="label">📖 متوسط المراجعة</div>
                </div>
                <div class="month-stat">
                    <div class="num">{{ month.avg_homework|default(0, true) }}</div>
                    <div class="label">📝 متوسط الواجب</div>
                </div>
                <div class="month-stat">
                    <div class="num">{{ month.completed_sessions|default(0, true) }}</div>
                    <div class="label">✅ حصص مكتملة</div>
                </div>
                <div class="month-stat">
                    <div class="num">{{ month.pending_sessions|default(0, true) }}</div>
                    <div class="label">⏳ حصص معلقة</div>
                </div>
            </div>

            <!-- مخططات الشهر -->
            <div class="charts-grid">
                <div class="chart-panel">
                    <div class="panel-header">
                        <h3>📈 تطور الأداء في {{ month.name }}</h3>
                    </div>
                    <div class="chart-container">
                        <canvas id="chart-{{ month.id }}"></canvas>
                    </div>
                </div>
                <div class="chart-panel">
                    <div class="panel-header">
                        <h3>📊 توزيع الدرجات</h3>
                    </div>
                    <div class="chart-container">
                        <canvas id="dist-{{ month.id }}"></canvas>
                    </div>
                </div>
            </div>

            <!-- جدول حصص الشهر -->
            <div class="table-panel">
                <div class="panel-header">
                    <h3>📋 حصص شهر {{ month.name }}</h3>
                    <div style="display:flex;gap:4px;">
                        <button class="btn btn-xs btn-outline" onclick="filterSessions('{{ month.id }}', 'all')">📋 الكل</button>
                        <button class="btn btn-xs btn-outline" onclick="filterSessions('{{ month.id }}', 'high')">⭐ عالي</button>
                        <button class="btn btn-xs btn-outline" onclick="filterSessions('{{ month.id }}', 'low')">📉 منخفض</button>
                    </div>
                </div>
                <div class="table-responsive">
                    <table>
                        <thead>
                            <tr>
                                <th>#</th>
                                <th>📅 التاريخ</th>
                                <th>📖 الحفظ</th>
                                <th>⭐ درجة الحفظ</th>
                                <th>📖 المراجعة</th>
                                <th>⭐ درجة المراجعة</th>
                                <th>📝 الواجب</th>
                                <th>📝 ملاحظات</th>
                                <th>✅ الحالة</th>
                            </tr>
                        </thead>
                        <tbody id="sessionsBody-{{ month.id }}">
                            {% if month.sessions and month.sessions|length > 0 %}
                                {% for session in month.sessions %}
                                <tr class="{% if (session.score_save|default(0, true)) + (session.score_rev|default(0, true)) + (session.homework_score|default(0, true)) >= 20 %}high-score{% elif (session.score_save|default(0, true)) + (session.score_rev|default(0, true)) + (session.homework_score|default(0, true)) <= 10 %}low-score{% endif %}">
                                    <td>{{ loop.index }}</td>
                                    <td>{{ session.date or '—' }}</td>
                                    <td>{{ session.curr_save or '-' }}</td>
                                    <td>{{ session.score_save|default(0, true) }}</td>
                                    <td>{{ session.curr_rev or '-' }}</td>
                                    <td>{{ session.score_rev|default(0, true) }}</td>
                                    <td>{{ session.homework_score|default(0, true) }}</td>
                                    <td>{{ session.notes or '-' }}</td>
                                    <td>
                                        <span class="session-badge {% if session.sent %}completed{% else %}pending{% endif %}">
                                            {% if session.sent %}✅ مكتمل{% else %}⏳ معلق{% endif %}
                                        </span>
                                    </td>
                                </tr>
                                {% endfor %}
                            {% else %}
                            <tr>
                                <td colspan="9" style="text-align:center;color:var(--text-muted);padding:20px 0;">
                                    📭 لا توجد حصص في هذا الشهر
                                </td>
                            </tr>
                            {% endif %}
                        </tbody>
                    </table>
                </div>
            </div>

        </div>
        {% endfor %}

        <!-- ===== التوصيات الذكية ===== -->
        <div class="recommendations">
            <div class="rec-card">
                <div class="title">💪 نقاط قوتك</div>
                <div class="desc">{{ strengths|default('أنت تظهر تقدماً ملحوظاً في الحفظ والمراجعة', true) }}</div>
                <span class="action good">✅ استمر على هذا المنوال</span>
            </div>
            <div class="rec-card">
                <div class="title">📈 مجالات التحسين</div>
                <div class="desc">{{ weaknesses|default('ركز على تحسين درجة الواجبات والمراجعة المنتظمة', true) }}</div>
                <span class="action warning">⚠️ تحتاج إلى مزيد من التركيز</span>
            </div>
            <div class="rec-card">
                <div class="title">📅 الخطة المقترحة</div>
                <div class="desc">{{ plan|default('خصص 30 دقيقة يومياً للمراجعة و15 دقيقة للواجبات', true) }}</div>
                <span class="action info">📋 خطة مخصصة</span>
            </div>
            <div class="rec-card">
                <div class="title">🎯 الأهداف القادمة</div>
                <div class="desc">{{ goals|default('الهدف: إكمال جميع حصص الشهر الحالي', true) }}</div>
                <span class="action good">🎯 هدف قابل للتحقيق</span>
            </div>
        </div>

    </div>

    <!-- ==========================================
    رسالة التنبيه (Toast)
    ========================================== -->
    <div class="toast" id="toast">
        <div class="title" id="toastTitle">✅ تم</div>
        <div class="message" id="toastMessage">تم تنفيذ العملية بنجاح</div>
    </div>

    <!-- ==========================================
    جافا سكريبت
    ========================================== -->
    <script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
    <script>
        let charts = {};
        let distributionCharts = {};

        /**
         * ==========================================
         * SECTION 1: دوال مساعدة
         * ==========================================
         */

        function showToast(type, title, message) {
            const toast = document.getElementById('toast');
            toast.className = 'toast show ' + type;
            document.getElementById('toastTitle').textContent = title;
            document.getElementById('toastMessage').textContent = message;

            clearTimeout(toast._timeout);
            toast._timeout = setTimeout(function() {
                toast.classList.remove('show');
            }, 4000);
        }

        function exportReport() {
            showToast('info', '📥', 'جاري تحضير التقرير للتصدير...');
            setTimeout(function() {
                showToast('success', '✅ تم', 'تم تصدير التقرير بنجاح');
            }, 1500);
        }

        function printReport() {
            window.print();
        }


        /**
         * ==========================================
         * SECTION 2: إدارة الشهور
         * ==========================================
         */

        function switchMonth(monthId) {
            // إخفاء جميع الشهور
            document.querySelectorAll('.month-content').forEach(function(el) {
                el.classList.remove('active');
            });

            // إزالة التفعيل من جميع التبويبات
            document.querySelectorAll('.month-tab').forEach(function(el) {
                el.classList.remove('active');
            });

            // إظهار الشهر المطلوب
            document.getElementById('month-' + monthId).classList.add('active');

            // تفعيل التبويب المناسب
            document.querySelector('.month-tab[data-month="' + monthId + '"]').classList.add('active');

            // تحديث المخططات
            setTimeout(function() {
                if (charts[monthId]) {
                    charts[monthId].resize();
                }
                if (distributionCharts[monthId]) {
                    distributionCharts[monthId].resize();
                }
            }, 100);
        }


        /**
         * ==========================================
         * SECTION 3: تصفية الحصص
         * ==========================================
         */

        function filterSessions(monthId, type) {
            const rows = document.querySelectorAll('#sessionsBody-' + monthId + ' tr');
            rows.forEach(function(row) {
                if (row.querySelector('td[colspan]')) return; // تخطي رسالة "لا توجد حصص"

                const scoreCells = row.querySelectorAll('td');
                if (scoreCells.length < 6) return;

                const saveScore = parseInt(scoreCells[3]?.textContent || 0);
                const revScore = parseInt(scoreCells[5]?.textContent || 0);
                const hwScore = parseInt(scoreCells[6]?.textContent || 0);
                const total = saveScore + revScore + hwScore;

                if (type === 'high') {
                    row.style.display = total >= 20 ? '' : 'none';
                } else if (type === 'low') {
                    row.style.display = total <= 10 ? '' : 'none';
                } else {
                    row.style.display = '';
                }
            });
        }


        /**
         * ==========================================
         * SECTION 4: تهيئة المخططات
         * ==========================================
         */

        function initCharts() {
            {% for month in months %}
            // مخطط الأداء
            const perfCtx = document.getElementById('chart-{{ month.id }}');
            if (perfCtx) {
                charts['{{ month.id }}'] = new Chart(perfCtx.getContext('2d'), {
                    type: 'line',
                    data: {
                        labels: {{ month.chart_labels|tojson }},
                        datasets: [
                            {
                                label: 'درجة الحفظ',
                                data: {{ month.chart_save|tojson }},
                                borderColor: '#e8c84a',
                                backgroundColor: 'rgba(232,200,74,0.08)',
                                tension: 0.4,
                                fill: true,
                                pointBackgroundColor: '#e8c84a',
                                pointBorderColor: '#1a1a1a',
                                pointBorderWidth: 2,
                                pointRadius: 4
                            },
                            {
                                label: 'درجة المراجعة',
                                data: {{ month.chart_rev|tojson }},
                                borderColor: '#4ade80',
                                backgroundColor: 'rgba(74,222,128,0.08)',
                                tension: 0.4,
                                fill: true,
                                pointBackgroundColor: '#4ade80',
                                pointBorderColor: '#1a1a1a',
                                pointBorderWidth: 2,
                                pointRadius: 4
                            },
                            {
                                label: 'درجة الواجب',
                                data: {{ month.chart_homework|tojson }},
                                borderColor: '#60a5fa',
                                backgroundColor: 'rgba(96,165,250,0.08)',
                                tension: 0.4,
                                fill: true,
                                pointBackgroundColor: '#60a5fa',
                                pointBorderColor: '#1a1a1a',
                                pointBorderWidth: 2,
                                pointRadius: 4
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: {
                                labels: {
                                    color: '#ffffff',
                                    font: { family: 'Tajawal', size: 11 },
                                    boxWidth: 12,
                                    padding: 8
                                }
                            }
                        },
                        scales: {
                            y: {
                                min: 0,
                                max: 10,
                                grid: { color: 'rgba(255,255,255,0.05)' },
                                ticks: { color: 'rgba(255,255,255,0.5)', font: { family: 'Tajawal' } }
                            },
                            x: {
                                grid: { display: false },
                                ticks: { color: 'rgba(255,255,255,0.5)', font: { family: 'Tajawal' } }
                            }
                        }
                    }
                });
            }

            // مخطط التوزيع
            const distCtx = document.getElementById('dist-{{ month.id }}');
            if (distCtx) {
                distributionCharts['{{ month.id }}'] = new Chart(distCtx.getContext('2d'), {
                    type: 'doughnut',
                    data: {
                        labels: ['ممتاز (8-10)', 'جيد (6-8)', 'متوسط (4-6)', 'ضعيف (0-4)'],
                        datasets: [{
                            data: {{ month.distribution_data|tojson }},
                            backgroundColor: ['#4ade80', '#e8c84a', '#fbbf24', '#f87171'],
                            borderColor: 'rgba(13,26,63,0.8)',
                            borderWidth: 3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: {
                                position: 'bottom',
                                labels: {
                                    color: '#ffffff',
                                    font: { family: 'Tajawal', size: 11 },
                                    boxWidth: 12,
                                    padding: 8
                                }
                            }
                        },
                        cutout: '60%'
                    }
                });
            }
            {% endfor %}
        }

        // ==========================================
        // SECTION 5: تشغيل التحميل
        // ==========================================

        document.addEventListener('DOMContentLoaded', function() {
            initCharts();
            console.log('📊 تقريري (بالشهور والحصص) جاهز');
            console.log('📅 عدد الشهور: {{ months|length }}');
            console.log('📚 إجمالي الحصص: {{ total_sessions }}');
        });
    </script>

</body>
</html>
'''
