@app.route('/api/notifications')
@login_required()
def api_notifications():
    """جلب آخر الإشعارات غير المقروءة للمستخدم الحالي (لقائمة الجرس)"""
    role = session.get('role')
    user_type = 'admin' if role == 'admin' else 'student'
    user_id = session.get('user_id')
    notes = get_recent_notifications(user_id, user_type)
    out = [{
        'id': n['id'],
        'type': 'message',
        'sender_name': n['sender_name'],
        'message': (n['message'] or '')[:100],
        'created_at': n['created_at']
    } for n in notes]
    return jsonify({'count': get_unread_count(user_id, user_type), 'notifications': out})
