_last_monthly_xp_check = {'date': None}
@app.before_request
def _auto_monthly_xp_hook():
    """تشغيل صرف XP الشهري التلقائي مرة واحدة على الأقل يومياً دون أي تدخل من المشرف"""
    today_str = get_today()
    if _last_monthly_xp_check['date'] != today_str:
        _last_monthly_xp_check['date'] = today_str
        try:
            run_monthly_xp_disbursement()
        except Exception:
            pass

