def home():
    """الصفحة الرئيسية"""
    stats = {
        'students_count': query_one("SELECT COUNT(*) as count FROM students WHERE status = 'active'")['count'],
        'evaluations_today': query_one("SELECT COUNT(*) as count FROM daily_evaluations WHERE date = ?", (get_today(),))['count'],
        'online_now': 3,
        'new_students_today': 1,
        'completion_rate': 85,
        'avg_progress': 70,
        'progress_change': 5
    }
    
    daily_verse = {
        'arabic': 'وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ',
        'translation': 'ولقد يسرنا القرآن للذكر فهل من مدكر — القمر 17'
    }
    daily_hadith = {
        'arabic': 'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ',
        'translation': 'خيركم من تعلم القرآن وعلمه — رواه البخاري'
    }
    
