@app.route('/admin/login', methods=['GET', 'POST'])
def admin_login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if not username or not password:
            flash('الرجاء إدخال اسم المستخدم وكلمة المرور', 'danger')
            return render_template_string(ADMIN_LOGIN_HTML)
        conn = get_db()
        try:
            cur = conn.cursor()
            cur.execute("SELECT * FROM admins WHERE username = %s", (username,))
            admin = cur.fetchone()
            cur.close()
            if admin and check_password_hash(admin['password'], password):
                create_session(admin['id'], 'admin', dict(admin))
                remember = bool(request.form.get('remember'))
                session.permanent = True
                app.permanent_session_lifetime = timedelta(days=30) if remember else timedelta(hours=8)
                flash(f'مرحباً {admin["name"]}', 'success')
                return redirect(url_for('admin_dashboard'))
            else:
                flash('اسم المستخدم أو كلمة المرور غير صحيحة', 'danger')
        finally:
            conn.close()
    return render_template_string(ADMIN_LOGIN_HTML)
