@app.route('/admin/evaluation')
@login_required('admin')
def evaluation():
    """صفحة التقييم وسجل الحصص"""
    students = get_active_students()
    months = query_all("""
        SELECT m.*, 
               (SELECT COUNT(*) FROM sessions WHERE month_id = m.id) as sessions_count
        FROM months m
        ORDER BY m.created_at DESC
    """)
    
    # جلب الحصص لكل شهر
    months = [dict(month) for month in months]
    for month in months:
        month['sessions'] = query_all("""
            SELECT s.*, st.name as student_name,
                   de.curr_save, de.score_save, de.curr_rev, de.score_rev, de.homework_score, de.notes, de.sent
            FROM sessions s
            LEFT JOIN students st ON st.id = s.student_id
            LEFT JOIN daily_evaluations de ON de.session_id = s.id
            WHERE s.month_id = ?
            ORDER BY s.date DESC, st.name ASC
        """, (month['id'],))
    
    total_sessions = query_one("SELECT COUNT(*) as count FROM sessions")['count']
    total_sent = query_one("SELECT COUNT(*) as count FROM daily_evaluations WHERE sent = 1")['count']
    total_pending = query_one("SELECT COUNT(*) as count FROM daily_evaluations WHERE sent = 0")['count']
    
    return render_template_string(EVALUATION_SESSIONS_HTML, 
                                   students=students, 
                                   months=months,
                                   total_sessions=total_sessions,
                                   total_sent=total_sent,
                                   total_pending=total_pending,
                                   datetime=datetime,
                                   timedelta=timedelta)
