@app.route('/admin/evaluation/add_session', methods=['POST'])
@login_required('admin')
def add_session():
    """إضافة حصة جديدة"""
    data = request.get_json()
    month_id = data.get('month_id')
    student_name = data.get('student_name')
    date = data.get('date', get_today())
    
    if not month_id or not student_name:
        return jsonify({'success': False, 'message': 'بيانات غير مكتملة'})
    
    # البحث عن الطالب
    student = query_one("SELECT * FROM students WHERE name = ? AND status = 'active'", (student_name,))
    if not student:
        return jsonify({'success': False, 'message': 'الطالب غير موجود'})
    
    # إنشاء الحصة
    session_id = execute_query("""
        INSERT INTO sessions (month_id, date, title, session_type, student_id)
        VALUES (?, ?, ?, ?, ?)
    """, (month_id, date, f"حصة {student_name}", 'حفظ', student['id']))
    
    # إنشاء تقييم للحصة
    execute_query("""
        INSERT INTO daily_evaluations (student_id, date, session_id)
        VALUES (?, ?, ?)
    """, (student['id'], date, session_id))
    
    return jsonify({'success': True, 'session_id': session_id})
@app.route('/admin/evaluation/add_session_all', methods=['POST'])
@login_required('admin')
def add_session_all():
    """تسجيل حصة لكل الطلاب النشطين دفعة واحدة"""
    data = request.get_json()
    month_id = data.get('month_id')
    date = data.get('date', get_today())
    
    if not month_id:
        return jsonify({'success': False, 'message': 'بيانات غير مكتملة'})
    
    students = get_active_students()
    if not students:
        return jsonify({'success': False, 'message': 'لا يوجد طلاب نشطون'})
    
    added_count = 0
    skipped_count = 0
    for student in students:
        # تفادي تكرار حصة لنفس الطالب في نفس اليوم داخل نفس الشهر
        existing = query_one("""
            SELECT s.id FROM sessions s
            WHERE s.month_id = ? AND s.date = ? AND s.student_id = ?
        """, (month_id, date, student['id']))
        if existing:
            skipped_count += 1
            continue
        
        session_id = execute_query("""
            INSERT INTO sessions (month_id, date, title, session_type, student_id)
            VALUES (?, ?, ?, ?, ?)
        """, (month_id, date, f"حصة {student['name']}", 'حفظ', student['id']))
        
        # إعادة استخدام تقييم موجود لنفس الطالب/التاريخ إن وجد، وإلا إنشاء واحد جديد
        existing_eval = query_one(
            "SELECT id FROM daily_evaluations WHERE student_id = ? AND date = ?",
            (student['id'], date)
        )
        if existing_eval:
            execute_query(
                "UPDATE daily_evaluations SET session_id = ? WHERE id = ?",
                (session_id, existing_eval['id'])
            )
        else:
            execute_query("""
                INSERT INTO daily_evaluations (student_id, date, session_id)
                VALUES (?, ?, ?)
            """, (student['id'], date, session_id))
        added_count += 1
    
    message = f'تم تسجيل الحصة لـ {added_count} طالب'
    if skipped_count:
        message += f' (تم تجاوز {skipped_count} كان لديهم حصة مسجلة مسبقاً بنفس التاريخ)'
    return jsonify({'success': True, 'added_count': added_count, 'skipped_count': skipped_count, 'message': message})
