@app.route('/admin/evaluation/send_sessions', methods=['POST'])
@login_required('admin')
def send_sessions():
    """إرسال التقييمات للطلاب ومكافأتهم تلقائياً بنقاط XP حسب درجاتهم"""
    data = request.get_json()
    session_ids = data.get('session_ids', [])
    
    if not session_ids:
        return jsonify({'success': False, 'message': 'لا توجد جلسات محددة'})
    
    sent_count = 0
    for session_id in session_ids:
        eval_row = query_one(
            "SELECT * FROM daily_evaluations WHERE session_id = ?",
            (session_id,)
        )
        # تحديث حالة الإرسال
        execute_query(
            "UPDATE daily_evaluations SET sent = 1 WHERE session_id = ?",
            (session_id,)
        )
        # مكافأة تلقائية بنقاط XP حسب درجات الحفظ والمراجعة والواجب
        if eval_row and eval_row['student_id']:
            score_save = eval_row['score_save'] or 0
            score_rev = eval_row['score_rev'] or 0
            homework_score = eval_row['homework_score'] or 0
            xp_reward = round((score_save + score_rev + homework_score) * 5)
            if xp_reward > 0:
                add_points(eval_row['student_id'], xp_reward, f"مكافأة تقييم تلقائية - حصة #{session_id}", 'earned')
        sent_count += 1
    
    return jsonify({'success': True, 'sent_count': sent_count})
