@app.route('/admin/homework/add', methods=['POST'])
@login_required('admin')
def add_homework():
    """إضافة واجب جديد"""
    homework_type = request.form.get('homework_type')
    details = request.form.get('details')
    due_date = request.form.get('due_date', get_today())
    notes = request.form.get('notes', '')
    send_now = request.form.get('send_now') == 'on'
    
    if not details:
        return jsonify({'success': False, 'message': 'تفاصيل الواجب مطلوبة'})
    
    student_ids = []
    if homework_type == 'جماعي':
        # جميع الطلاب النشطين
        students = get_active_students()
        student_ids = [s['id'] for s in students]
    elif homework_type == 'فردي':
        student_ids = request.form.getlist('student_ids[]')
    elif homework_type == 'مجموعة':
        student_ids = request.form.getlist('student_ids[]')
    
    if not student_ids:
        return jsonify({'success': False, 'message': 'لم يتم اختيار أي طالب'})
    
    # إضافة الواجب لكل طالب
    for student_id in student_ids:
        execute_query("""
            INSERT INTO homework (student_id, date, details, notes, sent)
            VALUES (?, ?, ?, ?, ?)
        """, (student_id, due_date, details, notes, 1 if send_now else 0))
    
    return jsonify({'success': True, 'message': f'تم إضافة الواجب لـ {len(student_ids)} طالب'})
