@login_required('admin')
def toggle_competition(comp_id):
    """تبديل حالة المسابقة، ومكافأة الفائز تلقائياً عند إغلاق المسابقة"""
    comp = get_competition_by_id(comp_id)
    if comp:
        was_active = comp['active'] == 1
        update_competition(comp_id, {'active': 1 if comp['active'] == 0 else 0})
        # عند إغلاق مسابقة كانت نشطة، كافئ الفائز تلقائياً (مرة واحدة فقط لكل مسابقة)
        if was_active and not comp['rewarded']:
            grades = get_competition_grades(comp_id)
            if grades and grades[0]['grade'] and grades[0]['grade'] > 0:
                winner = grades[0]
                add_points(winner['student_id'], 100, f"فوز في مسابقة: {comp['name']}", 'earned')
                winner_badge = query_one("SELECT id FROM badges WHERE code = 'competition_winner'")
                if winner_badge:
                    already = query_one(
                        "SELECT student_id FROM student_badges WHERE student_id = ? AND badge_id = ?",
                        (winner['student_id'], winner_badge['id'])
                    )
                    if not already:
                        execute_query(
                            "INSERT INTO student_badges (student_id, badge_id) VALUES (?, ?)",
                            (winner['student_id'], winner_badge['id'])
                        )
                execute_query("UPDATE competitions SET rewarded = 1 WHERE id = ?", (comp_id,))
        return jsonify({'success': True})
    return jsonify({'success': False})
