@app.route('/admin/competitions/save_grades', methods=['POST'])
@login_required('admin')
def save_competition_grades():
    """حفظ درجات المسابقات"""
    grades = request.form.get('grades', {})
    
    for student_key, comp_grades in grades.items():
        student_id = student_key.split('[')[1].split(']')[0] if '[' in student_key else student_key
        for comp_key, grade in comp_grades.items():
            comp_id = comp_key.split('[')[1].split(']')[0] if '[' in comp_key else comp_key
            note_key = f"grade_notes[{student_id}][{comp_id}]"
            note = request.form.get(note_key, '')
            
            if grade:
                update_competition_grade(int(student_id), int(comp_id), float(grade), note)
    
    # حساب المجاميع والترتيب
    totals = {}
    competitions_list = get_all_competitions()
    students = get_active_students()
    
    for student in students:
        total = 0
        for comp in competitions_list:
            grade = get_student_competition_grade(student['id'], comp['id'])
            if grade:
                total += grade['grade']
        totals[student['id']] = total
    
    return jsonify({'success': True, 'totals': totals})
