@app.route('/admin/messages/check_new/<type>/<int:id>')
@login_required('admin')
def check_new_admin_messages(type, id):
    """التحقق من الرسائل الجديدة للمشرف"""
    admin_id = session['user_id']
    
    if type == 'user':
        messages = query_all("""
            SELECT * FROM messages 
            WHERE receiver_id = ? AND receiver_type = 'admin' AND sender_id = ? AND sender_type = 'student' AND is_read = 0
              AND (is_group = 0 OR is_group IS NULL)
            ORDER BY created_at DESC
        """, (admin_id, id))
    else:
        messages = query_all("""
            SELECT * FROM messages 
            WHERE group_id = ? AND receiver_id = ? AND is_read = 0
            ORDER BY created_at DESC
        """, (id, admin_id))
    
    return jsonify({
        'success': True,
        'new_messages': [dict(m) for m in messages]
    })
