@app.route('/admin/messages/clear_chat', methods=['POST'])
@login_required('admin')
def clear_admin_chat():
    """مسح محادثة المشرف"""
    data = request.get_json()
    id = data.get('id')
    type = data.get('type')
    
    if type == 'user':
        execute_query("""
            DELETE FROM messages 
            WHERE ((sender_id = ? AND sender_type = 'admin' AND receiver_id = ? AND receiver_type = 'student')
               OR (sender_id = ? AND sender_type = 'student' AND receiver_id = ? AND receiver_type = 'admin'))
              AND (is_group = 0 OR is_group IS NULL)
        """, (session['user_id'], id, id, session['user_id']))
    elif type == 'group':
        execute_query(
            "DELETE FROM messages WHERE group_id = ?",
            (id,)
        )
    
    return jsonify({'success': True})


@app.route('/admin/student/<int:student_id>')
@login_required(role='admin')
def admin_view_student(student_id):
    """عرض ملف طالب من قبل المشرف"""
    student = get_student_by_id(student_id)
    if not student:
        flash('الطالب غير موجود', 'danger')
        return redirect(url_for('manage_students'))

    student = dict(student)

    # الإحصائيات
    evaluations_count = query_one(
        "SELECT COUNT(*) as count FROM daily_evaluations WHERE student_id = ?",
        (student_id,)
    )['count']

    competitions_count = query_one(
        "SELECT COUNT(*) as count FROM competition_grades WHERE student_id = ?",
        (student_id,)
    )['count']

    badges = get_badges_with_status(student_id)
    points = get_student_points(student_id)
    rank = get_student_rank(student_id)
    recent_evals = get_student_evaluations(student_id, limit=10)
    homework_list = get_student_homework(student_id)
    student_groups = query_all(
        "SELECT g.* FROM message_groups g JOIN group_members gm ON g.id = gm.group_id WHERE gm.student_id = ?",
        (student_id,)
    )

    return render_template_string(ADMIN_VIEW_STUDENT_HTML,
                                   admin=get_current_user(),
                                   student=student,
                                   badges=badges,
                                   points=points,
                                   rank=rank,
                                   evaluations_count=evaluations_count,
                                   competitions_count=competitions_count,
                                   recent_evals=recent_evals,
                                   homework_list=homework_list,
                                   student_groups=student_groups,
                                   datetime=datetime)

