@app.route('/admin/profile/update', methods=['POST'])
@login_required('admin')
def update_admin_profile():
    """تحديث ملف المشرف"""
    admin = get_current_user()
    name = request.form.get('name')
    email = request.form.get('email')
    phone = request.form.get('phone')
    password = request.form.get('password')
    
    if not name:
        return jsonify({'success': False, 'message': 'الاسم مطلوب'})
    
    updates = {'name': name, 'email': email, 'phone': phone}
    if password:
        updates['password'] = generate_password_hash(password)
    
    execute_query(
        f"UPDATE admins SET {', '.join([f'{k} = ?' for k in updates.keys()])} WHERE id = ?",
        [v for v in updates.values()] + [admin['id']]
    )
    
    return jsonify({'success': True, 'message': 'تم تحديث الملف بنجاح'})
@app.route('/admin/assistants')
@login_required('admin')
def admin_assistants():
    """إدارة مساعدي المشرف"""
    assistants_list = get_assistants()
    students = get_active_students()
    today = get_today()
    next_month_date = (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d')
    
    # إضافة بيانات إضافية لكل مساعد
    assistants_list = [dict(assistant) for assistant in assistants_list]
    for assistant in assistants_list:
        assistant['student_name'] = assistant['name']
        assistant['email'] = assistant['email']
        assistant['is_admin'] = False
        
        # عدد الإجراءات
        actions = query_one(
            "SELECT COUNT(*) as count FROM assistant_actions WHERE assistant_id = ?",
            (assistant['id'],)
        )
        assistant['actions_count'] = actions['count'] if actions else 0
        
        # XP
        assistant['xp_points'] = assistant.get('xp_points', 0)
        assistant['xp_due_date'] = assistant.get('xp_due_date', '')
        assistant['last_xp_granted'] = assistant.get('last_xp_granted', '')
    
    return render_template_string(ASSISTANTS_HTML,
                                   assistants=assistants_list,
                                   students=students,
                                   next_month_date=next_month_date,
                                   today=today,
                                   datetime=datetime)
@app.route('/admin/assistants/add', methods=['POST'])
@login_required('admin')
def add_assistant():
    """منح صلاحيات مساعد لطالب"""
    student_id = request.form.get('student_id')
    permissions = request.form.getlist('permissions')
    xp_due_date = request.form.get('xp_due_date', get_today())
    
    if not student_id:
        return jsonify({'success': False, 'message': 'الرجاء اختيار طالب'})
    
    if not permissions:
        return jsonify({'success': False, 'message': 'الرجاء اختيار صلاحية واحدة على الأقل'})
    
    # التحقق من الحد الأقصى للمساعدين
    count = query_one("SELECT COUNT(*) as count FROM assistants WHERE active = 1")['count']
    if count >= 5:
        return jsonify({'success': False, 'message': 'الحد الأقصى 5 مساعدين نشطين'})
    
    grant_assistant(student_id, ','.join(permissions), xp_due_date)
    return jsonify({'success': True, 'message': 'تم منح الصلاحيات بنجاح'})
