@app.route('/admin/assistants/reset_xp_due_date/<int:assistant_id>', methods=['POST'])
@login_required('admin')
def reset_assistant_xp_due_date(assistant_id):
    """تحديث تاريخ استحقاق XP للمساعد"""
    next_month = (datetime.now() + timedelta(days=30)).strftime('%Y-%m-%d')
    execute_query(
        "UPDATE assistants SET xp_due_date = ? WHERE id = ?",
        (next_month, assistant_id)
    )
    return jsonify({'success': True, 'message': 'تم تجديد المنحة للشهر القادم'})
@app.route('/admin/duels')
@login_required('admin')
def admin_duels():
    """إدارة التحديات الفردية"""
    duels = query_all("""
        SELECT d.*,
               c.name as challenger_name,
               o.name as opponent_name,
               w.name as winner_name
        FROM duels d
        JOIN students c ON c.id = d.challenger_id
        JOIN students o ON o.id = d.opponent_id
        LEFT JOIN students w ON w.id = d.winner_id
        ORDER BY d.created_at DESC
    """)
    
    return render_template_string(ADMIN_DUELS_HTML, duels=duels, datetime=datetime)
@app.route('/admin/duels/action', methods=['POST'])
@login_required('admin')
def duel_action():
    """تنفيذ إجراء على تحدي"""
    duel_id = request.form.get('duel_id')
    action = request.form.get('action')
    winner_id = request.form.get('winner_id')
    
    if action == 'approve':
        update_duel_status(duel_id, 'accepted')
    elif action == 'reject':
        update_duel_status(duel_id, 'rejected')
    elif action == 'result':
        if winner_id:
            update_duel_status(duel_id, 'completed', winner_id)
        else:
            return jsonify({'success': False, 'message': 'الرجاء اختيار الفائز'})
    
    return jsonify({'success': True})
