@app.route('/admin/store/add_book', methods=['POST'])
@login_required('admin')
def add_admin_book():
    """إضافة كتاب في المتجر"""
    title = request.form.get('title')
    author = request.form.get('author')
    description = request.form.get('description')
    price_points = request.form.get('price_points', 10)
    quantity = request.form.get('quantity', 1)
    
    if not title:
        return jsonify({'success': False, 'message': 'عنوان الكتاب مطلوب'})
    
    # رفع ملف PDF
    pdf_file = request.files.get('pdf_file')
    pdf_url = request.form.get('pdf_url')
    
    if pdf_file and pdf_file.filename:
        pdf_url = save_uploaded_file(pdf_file, 'books')
    
    # رفع صورة الغلاف
    cover_file = request.files.get('cover_file')
    cover_url = request.form.get('cover_url')
    
    if cover_file and cover_file.filename:
        cover_url = save_uploaded_file(cover_file, 'books')
    
    book_data = {
        'title': title,
        'author': author,
        'description': description,
        'price_points': int(price_points),
        'quantity': int(quantity),
        'cover_url': cover_url,
        'pdf_url': pdf_url,
        'active': 1
    }
    
    create_book(book_data)
    return jsonify({'success': True, 'message': 'تم إضافة الكتاب بنجاح'})
