@app.route('/student/login', methods=['GET', 'POST'])
def student_login():
    """صفحة دخول الطالب"""
    if request.method == 'POST':
        email = request.form.get('email')
        password = request.form.get('password')
        
        student = get_student_by_email(email)
        if student and check_password_hash(student['password'], password):
            if student['status'] == 'inactive':
                flash('حسابك غير نشط، يرجى التواصل مع المشرف', 'danger')
                return redirect(url_for('student_login'))
            
            create_student_session(student['id'], student['name'], student['email'])
            remember = bool(request.form.get('remember'))
            session.permanent = True
            app.permanent_session_lifetime = timedelta(days=30) if remember else timedelta(hours=8)
            flash('مرحباً بك ' + student['name'], 'success')
            return redirect(url_for('student_dashboard'))
        else:
            flash('البريد الإلكتروني أو كلمة المرور غير صحيحة', 'danger')
    
    # بيانات المتابعة
    streak = {
        'days': 7,
        'today_points': 15,
        'total_points': query_one("SELECT points FROM students WHERE id = 1")['points'] if query_one("SELECT points FROM students WHERE id = 1") else 0
    }
    
    return render_template_string(STUDENT_LOGIN_HTML, streak=streak, datetime=datetime)
@app.route('/student/register', methods=['GET', 'POST'])
def student_register():
    """صفحة تسجيل طالب جديد"""
    if request.method == 'POST':
        name = request.form.get('name')
        email = request.form.get('email')
        password = request.form.get('password')
        password_confirm = request.form.get('password_confirm')
        phone = request.form.get('phone')
        parent_phone = request.form.get('parent_phone')
        address = request.form.get('address')
        
        if not all([name, email, password, phone, parent_phone, address]):
            flash('جميع الحقول المطلوبة يجب تعبئتها', 'danger')
            return render_template_string(STUDENT_REGISTER_HTML, datetime=datetime)
        
        if password != password_confirm:
            flash('كلمة المرور غير متطابقة', 'danger')
            return render_template_string(STUDENT_REGISTER_HTML, datetime=datetime)
        
        if len(password) < 6:
            flash('كلمة المرور يجب أن تكون 6 أحرف على الأقل', 'danger')
            return render_template_string(STUDENT_REGISTER_HTML, datetime=datetime)
        
        # التحقق من وجود البريد
        existing = get_student_by_email(email)
        if existing:
            flash('البريد الإلكتروني مسجل بالفعل', 'danger')
            return render_template_string(STUDENT_REGISTER_HTML, datetime=datetime)
        
        # إنشاء طلب تسجيل
        hashed_password = generate_password_hash(password)
        execute_query("""
            INSERT INTO registration_requests (name, email, password, phone, parent_phone, address)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (name, email, hashed_password, phone, parent_phone, address))
        
        flash('تم إرسال طلب التسجيل بنجاح، سيتم مراجعته من قبل المشرف', 'success')
        return redirect(url_for('student_login'))
    
    return render_template_string(STUDENT_REGISTER_HTML, datetime=datetime)
