@app.route('/student/submit_homework', methods=['POST'])
@login_required('student')
def submit_homework_route():
    """تسليم واجب"""
    student = get_current_user()
    homework_id = request.form.get('homework_id')
    content = request.form.get('content')
    file = request.files.get('file')
    audio_data = request.form.get('audio_data')
    
    if not homework_id:
        return jsonify({'success': False, 'message': 'بيانات غير صالحة'})
    
    homework_exists = query_one("SELECT id FROM homework WHERE id = ?", (homework_id,))
    if not homework_exists:
        return jsonify({'success': False, 'message': 'الواجب غير موجود'})
    
    file_url = None
    if file and file.filename:
        file_url = save_uploaded_file(file, 'homework')
    
    # التعامل مع التسجيل الصوتي
    if audio_data:
        # حفظ الصوت كملف
        import base64
        audio_data = audio_data.replace('data:audio/webm;base64,', '')
        audio_bytes = base64.b64decode(audio_data)
        filename = f"audio_{datetime.now().strftime('%Y%m%d%H%M%S')}.webm"
        filepath = os.path.join(UPLOAD_FOLDER, 'homework', filename)
        os.makedirs(os.path.join(UPLOAD_FOLDER, 'homework'), exist_ok=True)
        with open(filepath, 'wb') as f:
            f.write(audio_bytes)
        file_url = f"/static/uploads/homework/{filename}"
    
    submit_homework(homework_id, student['id'], content, file_url)
    
    # منح نقاط للتسليم
    add_points(student['id'], 5, f"تسليم واجب #{homework_id}")
    
    return jsonify({'success': True, 'message': 'تم تسليم الواجب بنجاح'})
@app.route('/student/report')
@login_required('student')
def student_report():
    """تقرير الطالب المتطور"""
    student = get_current_user()
    
    # جلب جميع الشهور
    months_list = query_all("""
        SELECT m.*,
               (SELECT COUNT(*) FROM sessions s WHERE s.month_id = m.id) as sessions_count
        FROM months m
        ORDER BY m.created_at DESC
    """)
    
    total_sessions = 0
    total_months = len(months_list)
    total_score = 0
    
    months_list = [dict(month) for month in months_list]
    for month in months_list:
        # جلب حصص الشهر للطالب
        sessions = query_all("""
            SELECT s.*, 
                   de.curr_save, de.score_save, de.curr_rev, de.score_rev, de.homework_score, de.notes, de.sent
            FROM sessions s
            LEFT JOIN daily_evaluations de ON de.session_id = s.id AND de.student_id = ?
            WHERE s.month_id = ?
            ORDER BY s.date DESC
        """, (student['id'], month['id']))
        
        month['sessions'] = sessions
        month['total_sessions'] = len(sessions)
        month['completed_sessions'] = sum(1 for s in sessions if s['sent'])
        month['pending_sessions'] = month['total_sessions'] - month['completed_sessions']
        
        # متوسطات الشهر
        save_scores = [s['score_save'] for s in sessions if s['score_save'] is not None]
        rev_scores = [s['score_rev'] for s in sessions if s['score_rev'] is not None]
        hw_scores = [s['homework_score'] for s in sessions if s['homework_score'] is not None]
        
        month['avg_save'] = round(sum(save_scores) / len(save_scores), 1) if save_scores else 0
        month['avg_rev'] = round(sum(rev_scores) / len(rev_scores), 1) if rev_scores else 0
        month['avg_homework'] = round(sum(hw_scores) / len(hw_scores), 1) if hw_scores else 0
        
        # بيانات المخططات
        month['chart_labels'] = [f"جلسة {i+1}" for i in range(len(sessions))]
        month['chart_save'] = [s['score_save'] or 0 for s in sessions]
        month['chart_rev'] = [s['score_rev'] or 0 for s in sessions]
        month['chart_homework'] = [s['homework_score'] or 0 for s in sessions]
        
        # توزيع الدرجات
        total_grades = []
        for s in sessions:
            total_grades.append((s['score_save'] or 0) + (s['score_rev'] or 0) + (s['homework_score'] or 0))
        
        dist = [0, 0, 0, 0]  # ممتاز، جيد، متوسط، ضعيف
        for g in total_grades:
            if g >= 24:
                dist[0] += 1
            elif g >= 18:
                dist[1] += 1
            elif g >= 12:
                dist[2] += 1
            else:
                dist[3] += 1
        month['distribution_data'] = dist
        
        total_sessions += len(sessions)
        total_score += sum(total_grades)
    
    # الإحصائيات العامة
    avg_save = query_one(
        "SELECT AVG(score_save) as avg FROM daily_evaluations WHERE student_id = ?",
        (student['id'],)
    )['avg'] or 0
    
    avg_rev = query_one(
        "SELECT AVG(score_rev) as avg FROM daily_evaluations WHERE student_id = ?",
        (student['id'],)
    )['avg'] or 0
    
    avg_hw = query_one(
        "SELECT AVG(homework_score) as avg FROM daily_evaluations WHERE student_id = ?",
        (student['id'],)
    )['avg'] or 0
    
    # توصيات ذكية
    strengths = "أنت تظهر تقدماً ملحوظاً في الحفظ والمراجعة"
    weaknesses = "ركز على تحسين درجة الواجبات والمراجعة المنتظمة"
    plan = "خصص 30 دقيقة يومياً للمراجعة و15 دقيقة للواجبات"
    goals = "الهدف: إكمال جميع حصص الشهر الحالي"
    
    return render_template_string(STUDENT_REPORT_HTML,
                                   student=student,
                                   months=months_list,
                                   total_months=total_months,
                                   total_sessions=total_sessions,
                                   total_score=total_score,
                                   avg_save=round(avg_save, 1),
                                   avg_rev=round(avg_rev, 1),
                                   avg_homework=round(avg_hw, 1),
                                   strengths=strengths,
                                   weaknesses=weaknesses,
                                   plan=plan,
                                   goals=goals,
                                   datetime=datetime)
