@app.route('/student/duels/create', methods=['POST'])
@login_required('student')
def create_duel_route():
    """إنشاء تحدي جديد"""
    student = get_current_user()
    
    opponent_id = request.form.get('opponent_id')
    duel_type = request.form.get('duel_type')
    custom_type = request.form.get('custom_type')
    wager_points = request.form.get('wager_points', 10)
    
    if not opponent_id or not duel_type:
        return jsonify({'success': False, 'message': 'بيانات غير صالحة'})
    
    # التحقق من وجود خصم
    opponent = get_student_by_id(opponent_id)
    if not opponent or opponent['status'] != 'active':
        return jsonify({'success': False, 'message': 'الخصم غير متاح'})
    
    # التحقق من النقاط
    if int(wager_points) > student['points']:
        return jsonify({'success': False, 'message': 'لا تملك نقاط كافية للرهان'})
    
    duel_id = create_duel(student['id'], opponent_id, duel_type, int(wager_points), custom_type)
    
    return jsonify({'success': True, 'message': 'تم إرسال التحدي بنجاح', 'duel_id': duel_id})
@app.route('/leaderboard')
def leaderboard():
    """لوحة الصدارة"""
    top_students = query_all("""
        SELECT id, name, points, rank, status
        FROM students
        WHERE status = 'active'
        ORDER BY points DESC
        LIMIT 50
    """)
    
    # إضافة بيانات إضافية
    top_students = [dict(student) for student in top_students]
    for student in top_students:
        student['badges'] = get_student_badges(student['id'])
    
    return render_template_string(LEADERBOARD_HTML,
                                   top_students=top_students,
                                   datetime=datetime)
